import Foundation
import Testing
@testable import VistaCore

/// Generated bytes and explicit callback gates only. No SMB, media, network or device work.
@Suite(.serialized) @MainActor struct PlaybackForwardProgressTests {
    private let file = try! MediaFile(components: ["generated-forward-progress.mp4"])
    #if VISTA_FORWARD_BASELINE_COMPARISON
    private static let baseline95 = true
    #else
    private static let baseline95 = false
    #endif
    @MainActor private final class Source: PlaybackCacheSource {
        var token: UInt64? = 1, active = true, stopped = false
        var supportsRetainedCacheRevalidation: Bool { true }
        var isPlaybackRecovering: Bool { false }
        var recoveryActiveStartedAt: TimeInterval? { nil }
        var recoveryActiveElapsed: TimeInterval { 0 }
        var demands: [Range<UInt64>] = [], speculation: [Range<UInt64>] = []
        var blockedDemand: Range<UInt64>?, blockedPrefetch: Int?
        var demandGate: CheckedContinuation<Void, Never>?, prefetchGate: CheckedContinuation<Void, Never>?
        var outstanding = 0, maxOutstanding = 0
        var rejectCachedSegments = false, failDemand = false, blockAllDemands = false
        static func bytes(_ range: Range<UInt64>, epoch: UInt64 = 1) -> Data {
            var result = Data(count: range.count)
            result.withUnsafeMutableBytes { raw in
                let bytes = raw.bindMemory(to: UInt8.self)
                for i in bytes.indices {
                    let p = range.lowerBound + UInt64(i)
                    bytes[i] = UInt8(truncatingIfNeeded: p &+ (p >> 12) &+ (p >> 20) &+ epoch)
                }
            }
            return result
        }
        func playbackCacheEpoch() throws -> UInt64? { stopped || !active ? nil : token }
        func fileSize(for file: MediaFile) async throws -> UInt64 { 512 * 1_048_576 }
        func read(_ file: MediaFile, range: Range<UInt64>) async throws -> Data {
            demands.append(range); outstanding += 1; maxOutstanding = max(maxOutstanding, outstanding)
            defer { outstanding -= 1 }
            if blockedDemand == range || blockAllDemands { await withCheckedContinuation { demandGate = $0 } }
            try Task.checkCancellation()
            if failDemand { throw NSError(domain: "synthetic-source-failure", code: 1) }
            return Self.bytes(range, epoch: token ?? 1)
        }
        func readForPrefetch(_ file: MediaFile, range: Range<UInt64>) async throws -> Data {
            speculation.append(range); outstanding += 1; maxOutstanding = max(maxOutstanding, outstanding)
            defer { outstanding -= 1 }
            if blockedPrefetch == speculation.count { await withCheckedContinuation { prefetchGate = $0 } }
            return Self.bytes(range, epoch: token ?? 1)
        }
        func readCompletingCachedSegments(_ file: MediaFile, range: Range<UInt64>, segments: [PlaybackCachedSegment], epoch: UInt64) async throws -> PlaybackCachedReadResult {
            if token != epoch || rejectCachedSegments { return .init(data: try await read(file, range: range), usedCachedBytes: 0) }
            var result = Data(), cursor = range.lowerBound, used = 0
            for segment in segments {
                if cursor < segment.range.lowerBound { result.append(try await read(file, range: cursor..<segment.range.lowerBound)) }
                result.append(segment.data); used += segment.data.count; cursor = segment.range.upperBound
            }
            if cursor < range.upperBound { result.append(try await read(file, range: cursor..<range.upperBound)) }
            try Task.checkCancellation()
            return .init(data: result, usedCachedBytes: used)
        }
        func releaseDemand() { blockedDemand = nil; blockAllDemands = false; let saved = demandGate; demandGate = nil; saved?.resume() }
        func releasePrefetch() { blockedPrefetch = nil; let saved = prefetchGate; prefetchGate = nil; saved?.resume() }
        func setPlaybackSceneActive(_ active: Bool) { self.active = active }
        func cancelPlayback() { stopped = true }
        func awaitPlaybackCleanup() async throws {}
    }
    private func fieldIsPresent(_ s: PlaybackPrefetchSource, _ name: String) -> Bool {
        guard let value = Mirror(reflecting: s).children.first(where: { $0.label == name })?.value else { return false }
        return !Mirror(reflecting: value).children.isEmpty
    }
    private func until(_ predicate: @MainActor () -> Bool) async throws {
        let deadline = ProcessInfo.processInfo.systemUptime + 2
        while ProcessInfo.processInfo.systemUptime < deadline {
            if predicate() { return }
            await Task.yield()
        }
        throw NSError(domain: "forward-progress-synthetic-gate-timeout", code: 1)
    }
    private func settled(_ s: PlaybackPrefetchSource) async throws {
        try await until { !fieldIsPresent(s, "pump") }
    }
    private func make(_ b: Source, chunk: Int = 32, arena: Int = 2560) async throws -> PlaybackPrefetchSource {
        let s = PlaybackPrefetchSource(file: file, source: b,
            configuration: .init(capacityBytes: chunk * 2, chunkBytes: chunk, totalCapacityBytes: arena))
        _ = try await s.fileSize(for: file)
        s.setPrefetchEnabled(false, reason: .pause)
        try await settled(s)
        return s
    }
    private func read(_ s: PlaybackPrefetchSource, _ b: Source, _ range: Range<UInt64>) async throws {
        #expect(try await s.read(file, range: range) == Source.bytes(range, epoch: b.token ?? 1))
        #expect(b.maxOutstanding <= 1)
        #expect(s.metrics.validCacheBytes <= s.metrics.storageAllocatedBytes)
    }
    private func prime(_ s: PlaybackPrefetchSource, _ b: Source) async throws {
        try await read(s, b, 0..<16)
        try await read(s, b, 128..<160)
        try await read(s, b, 160..<192)
        try await settled(s)
    }
    private func cancel(_ s: PlaybackPrefetchSource, _ b: Source, _ range: Range<UInt64>) async throws {
        b.blockedDemand = range
        let task = Task { try await s.read(file, range: range) }
        try await until { b.demandGate != nil }
        task.cancel(); b.releaseDemand()
        do { _ = try await task.value; Issue.record("Cancelled synthetic demand returned bytes") }
        catch is CancellationError {}
        try await until { b.outstanding == 0 }; try await settled(s)
    }
    private func coverage(_ s: PlaybackPrefetchSource, _ range: Range<UInt64>) -> Int {
        s.rangeDiagnosticSnapshot().cache.reduce(0) { count, entry in
            let lower = max(range.lowerBound, entry.range.lower), upper = min(range.upperBound, entry.range.upper)
            return count + (upper > lower ? Int(upper - lower) : 0)
        }
    }
    private func record(_ scenario: String, _ fields: [String: Any]) throws {
        var result = fields
        result["scenario"] = scenario
        result["variant"] = Self.baseline95 ? "95" : "96"
        result["scope"] = "Generated Data; explicit synthetic priming and timing; not a device replay or throughput benchmark"
        let data = try JSONSerialization.data(withJSONObject: result, options: [.sortedKeys, .prettyPrinted])
        if let path = ProcessInfo.processInfo.environment["VISTA_FORWARD_COMPARISON_RESULTS"] {
            try FileManager.default.createDirectory(atPath: path, withIntermediateDirectories: true)
            try data.write(to: URL(fileURLWithPath: path).appendingPathComponent("\(scenario).json"))
        }
    }

    @Test(arguments: [0, 262_144, 327_680, 393_216, 524_288, 524_289] as [Int])
    func productionGapBoundaryKeepsFullPartialAndZeroBackreadsIndependent(gap: Int) async throws {
        let m: UInt64 = 1_048_576, b = Source()
        let s = try await make(b, chunk: 2 * 1_048_576, arena: 160 * 1_048_576)
        try await read(s, b, 0..<8)
        try await read(s, b, 8*m..<10*m); try await read(s, b, 10*m..<12*m)
        let initial = s.rangeDiagnosticSnapshot().forward
        #expect(initial.cursor == 12*m && initial.target == 16*m && initial.reads == 0)
        for r: Range<UInt64> in [0..<4, 4..<12, 20..<28] {
            try await read(s, b, r)
            let current = s.rangeDiagnosticSnapshot().forward
            #expect(current.cursor == initial.cursor && current.target == initial.target && current.reads == 0)
            #expect(!current.suspended)
        }
        let lower = 12*m + UInt64(gap)
        try await read(s, b, lower..<(lower + 65_536))
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == (gap <= 512*1024 ? lower + 65_536 : 12*m))
        #expect(b.speculation.isEmpty && b.maxOutstanding == 1)
        try await s.awaitPlaybackCleanup()
    }

    @Test func cancellationAndBackreadsPreserveOnlyExistingUnspentCredit() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        s.diagnosticSink = { record in
            if record.event == .retained, b.speculation.count == 1 { s.setPrefetchEnabled(false, reason: .pause) }
        }
        s.setPrefetchEnabled(true); try await settled(s); s.diagnosticSink = nil
        #expect(b.speculation == [192..<224])
        try await cancel(s, b, 320..<352)
        for r: Range<UInt64> in [0..<8, 8..<24, 32..<40] {
            try await read(s, b, r)
            let state = s.rangeDiagnosticSnapshot().forward
            #expect(state.cursor == 192 && !state.suspended && state.reads == 1 && state.target == 256)
        }
        s.setPrefetchEnabled(true); try await settled(s)
        #expect(b.speculation == [192..<224, 224..<256])
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 192)
        s.setPrefetchEnabled(false, reason: .pause)
        try await cancel(s, b, 352..<384); try await read(s, b, 0..<4)
        s.setPrefetchEnabled(true); try await settled(s)
        #expect(b.speculation.count == 2 && s.rangeDiagnosticSnapshot().forward.reads == 2)
        s.setPrefetchEnabled(false, reason: .pause); s.invalidatePrefetch(reason: .seek)
        try await cancel(s, b, 400..<432); try await read(s, b, 0..<4)
        s.setPrefetchEnabled(true); try await settled(s)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == nil && b.speculation.count == 2)
        try await s.awaitPlaybackCleanup()
    }

    #if !VISTA_FORWARD_BASELINE_COMPARISON
    @Test func successfulClassificationExcludesCancellationFailureAndRejectedCache() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b) // three zero-cache successes
        try await read(s, b, 0..<8) // full
        try await read(s, b, 8..<24) // eight cached, eight supplied
        try await read(s, b, 32..<40) // zero
        b.rejectCachedSegments = true
        try await read(s, b, 8..<28) // sixteen selected but source rejects all: zero
        b.rejectCachedSegments = false
        try await read(s, b, 0..<0) // empty is outside the success denominator
        let before = s.metrics.diagnostics
        #expect(before.demandFullCacheCount == 1 && before.demandPartialCacheCount == 1 && before.demandZeroCacheCount == 5)
        #expect(before.demandFullCacheCount + before.demandPartialCacheCount + before.demandZeroCacheCount == 7)
        #expect(before.demandSourceWaitCount == 6 && before.demandSourceCallCount == 6)
        try await cancel(s, b, 320..<352)
        b.failDemand = true
        do { _ = try await s.read(file, range: 360..<368); Issue.record("Expected generated source failure") }
        catch { #expect((error as NSError).domain == "synthetic-source-failure") }
        b.failDemand = false; try await settled(s)
        let after = s.metrics.diagnostics
        #expect(after.demandCancelledCount == 1 && after.demandFailedCount == 1)
        #expect(after.demandFullCacheCount == before.demandFullCacheCount && after.demandPartialCacheCount == before.demandPartialCacheCount && after.demandZeroCacheCount == before.demandZeroCacheCount)
        #expect(after.demandSourceWaitCount == before.demandSourceWaitCount && after.demandSourceCallCount == before.demandSourceCallCount && after.demandSourceWaitSeconds == before.demandSourceWaitSeconds)
        #expect(b.maxOutstanding == 1)
        try await s.awaitPlaybackCleanup()
    }
    #endif

    @Test func isolatedFarReadCannotBridgeBackreadAndSeekAllowsLowBootstrap() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        try await read(s, b, 400..<408)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 192)
        try await read(s, b, 0..<4)
        try await read(s, b, 408..<416)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 192)
        try await read(s, b, 416..<424)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 424)
        try await read(s, b, 4..<8); try await read(s, b, 8..<12)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 424)
        let retained = s.metrics.validCacheBytes
        s.invalidatePrefetch(reason: .seek)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == nil && s.metrics.validCacheBytes == retained)
        try await read(s, b, 4..<8)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == nil)
        try await read(s, b, 8..<12)
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == 12)
        try await s.awaitPlaybackCleanup()
    }

    /// One scaled byte is 64 KiB. 454...461 ranges and cancellation order are retained;
    /// initial lower history, paused priming and the following idle interval are synthetic.
    @Test func localTraceSufficientIdleConvertsFutureDemandToReadyHit() async throws {
        let b = Source(), s = try await make(b)
        var prefix: [[String: Any]] = []
        func trace(_ id: Int, _ range: Range<UInt64>) async throws {
            let covered = coverage(s, range)
            try await read(s, b, range)
            var entry: [String: Any] = ["originalWork": id, "range": [range.lowerBound, range.upperBound],
                "arrivalCoveredBytes": covered, "arrivalCoverage": covered == range.count ? "full" : (covered == 0 ? "zero" : "partial"),
                "actualUsedCachedBytes": s.rangeDiagnosticSnapshot().recent.last?.usedCachedBytes ?? -1]
            if let cursor = s.rangeDiagnosticSnapshot().forward.cursor { entry["cursorAfterSuccess"] = cursor }
            prefix.append(entry)
        }
        try await read(s, b, 2322..<2354); try await read(s, b, 2354..<2380)
        try await trace(454, 2846..<2878) // 177.875...179.875 MiB
        try await trace(455, 2878..<2910) // 179.875...181.875 MiB
        try await trace(456, 2322..<2323) // full low backread
        try await cancel(s, b, 2910..<2942) // 457: cancelled forward request
        try await trace(458, 2323..<2355) // full low backread
        try await trace(459, 2914..<2915) // 256 KiB forward gap
        try await trace(460, 2355..<2386) // 25/31 scaled bytes cached
        try await trace(461, 2915..<2916) // genuine high forward continuation
        #expect(s.rangeDiagnosticSnapshot().forward.cursor == (Self.baseline95 ? nil : 2916))
        s.setPrefetchEnabled(true); try await settled(s)
        #expect(b.speculation.count == (Self.baseline95 ? 0 : 2))
        var targets: [[String: Any]] = []
        let targetShapes: [(Int, Range<UInt64>)] = [(464, 2920..<2952), (470, 2958..<2990), (471, 2990..<3022)]
        for (index, item) in targetShapes.enumerated() {
            // An explicit opportunity BEFORE 470, never an invented 2ms slot between 470 and 471.
            // Works465...469 and their real timing are not reconstructed by this bounded experiment.
            if item.0 == 470 { s.setPrefetchEnabled(true); try await settled(s) }
            let needed: Range<UInt64> = item.1
            let covered = coverage(s, needed), sourceBefore = b.demands.count, pfBefore = b.speculation.count
            let expected = Self.baseline95 ? 0 : (index == 2 ? 22 : 32)
            #expect(covered == expected)
            s.setPrefetchEnabled(false, reason: .pause)
            b.blockAllDemands = true
            let demand = Task { try await s.read(file, range: needed) }
            try await until {
                b.demandGate != nil || s.rangeDiagnosticSnapshot().recent.contains {
                    $0.range?.lower == needed.lowerBound && $0.range?.upper == needed.upperBound && $0.result == .returned
                }
            }
            let targetNeededSourceGate = b.demandGate != nil
            if targetNeededSourceGate { b.releaseDemand() } else { b.blockAllDemands = false }
            #expect(targetNeededSourceGate == (covered < needed.count))
            #expect(try await demand.value == Source.bytes(needed)); try await settled(s)
            let used = s.rangeDiagnosticSnapshot().recent.last?.usedCachedBytes ?? -1
            #expect(used == covered && b.maxOutstanding == 1)
            #expect(b.demands.count - sourceBefore == (covered == needed.count ? 0 : 1))
            targets.append(["originalWorkShape": item.0, "range": [needed.lowerBound, needed.upperBound],
                "demandBytes": needed.count, "arrivalCoveredBytes": covered,
                "arrivalCoverage": covered == needed.count ? "full" : (covered == 0 ? "zero" : "partial"),
                "prefetchReadsBeforeDemand": pfBefore, "sourceDemandCallsForTarget": b.demands.count - sourceBefore,
                "sourceDemandRanges": b.demands.dropFirst(sourceBefore).map { [$0.lowerBound, $0.upperBound] },
                "targetNeededSourceGate": targetNeededSourceGate, "actualUsedCachedBytes": used, "bytesCorrect": true])
        }
        try record("local-trace-sufficient-idle", ["scaledByteBytes": 65_536, "prefix": prefix, "targets": targets,
            "prefetchRanges": b.speculation.map { [$0.lowerBound, $0.upperBound] }, "maxOutstanding": b.maxOutstanding,
            "timingAssumptions": "Synthetic priming; adequate idle after461 and464; no added idle between470 and471; works465...469 omitted, not reconstructed",
            "bytesCorrect": true])
        try await s.awaitPlaybackCleanup()
    }

    @Test func graceLetsQueuedDemandWinBeforePrefetchAdmission() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        let needed: Range<UInt64> = 192..<224
        b.blockedDemand = needed
        s.setPrefetchEnabled(true)
        try await until { fieldIsPresent(s, "idleGrace") }
        let covered = coverage(s, needed), before = b.demands.count
        let demand = Task { try await s.read(file, range: needed) }
        try await until { b.demandGate != nil }
        #expect(b.speculation.isEmpty && b.outstanding == 1)
        #expect(s.metrics.diagnostics.noAdmissionDemandOrGrace > 0)
        s.setPrefetchEnabled(false, reason: .pause); b.releaseDemand()
        #expect(try await demand.value == Source.bytes(needed)); try await settled(s)
        #expect(b.demands.count - before == 1 && b.maxOutstanding == 1)
        try record("demand-during-grace", ["arrivalCoveredBytes": covered, "arrivalCoverage": "zero",
            "sourceDemandCallsForTarget": b.demands.count - before, "prefetchReads": b.speculation.count,
            "demandGraceStops": s.metrics.diagnostics.noAdmissionDemandOrGrace,
            "speculativeWaitCount": s.metrics.speculativeWaitCount, "maxOutstanding": b.maxOutstanding, "bytesCorrect": true])
        try await s.awaitPlaybackCleanup()
    }

    @Test func queuedCancellationDuringGraceRestartsOnlyRemainingIdleAdmission() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        s.setPrefetchEnabled(true)
        try await until { fieldIsPresent(s, "idleGrace") }
        let before = b.demands.count
        var pending: Task<Data, any Error>?
        var cancelledAtEnqueue = false, observedGrace = false
        s.diagnosticSink = { event in
            if event.event == .demandEnqueued, !cancelledAtEnqueue {
                observedGrace = self.fieldIsPresent(s, "idleGrace")
                cancelledAtEnqueue = true
                pending?.cancel()
            }
        }
        pending = Task { try await s.read(file, range: 400..<432) }
        do { _ = try await pending!.value; Issue.record("Cancelled queue request returned bytes") }
        catch is CancellationError {}
        s.diagnosticSink = nil
        try await settled(s)
        #expect(cancelledAtEnqueue && observedGrace)
        #expect(b.demands.count == before)
        #expect(b.speculation == [192..<224, 224..<256])
        let window = s.rangeDiagnosticSnapshot().forward
        #expect(window.cursor == 192 && window.target == 256 && window.reads == 2)
        #expect(b.maxOutstanding == 1)
        try await s.awaitPlaybackCleanup()
    }

    @Test func synchronousCacheUseCancellationCannotRenewSpentForwardQuota() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        s.setPrefetchEnabled(true); try await settled(s)
        s.setPrefetchEnabled(false, reason: .pause)
        let before = s.rangeDiagnosticSnapshot().forward, retained = s.metrics.validCacheBytes
        #expect(before.cursor == 192 && before.target == 256 && before.reads == 2)
        #expect(b.speculation == [192..<224, 224..<256])
        var pending: Task<Data, any Error>?
        var cancelledAtCacheUse = false
        s.diagnosticSink = { event in
            if event.event == .prefixUsed, !cancelledAtCacheUse {
                cancelledAtCacheUse = true
                pending?.cancel()
            }
        }
        pending = Task { try await s.read(file, range: 192..<224) }
        do { _ = try await pending!.value; Issue.record("Synchronously cancelled cache demand returned bytes") }
        catch is CancellationError {}
        s.diagnosticSink = nil; try await settled(s)
        let after = s.rangeDiagnosticSnapshot().forward, retainedAfter = s.metrics.validCacheBytes
        #expect(cancelledAtCacheUse)
        #expect(after.cursor == before.cursor && after.target == before.target && after.reads == before.reads)
        #expect(s.metrics.validCacheBytes == retained && coverage(s, 192..<224) == 32)
        s.setPrefetchEnabled(true); try await settled(s)
        #expect(b.speculation == [192..<224, 224..<256])
        #expect(b.maxOutstanding == 1)
        try record("synchronous-cache-use-cancellation", ["cancelledAtCacheUse": cancelledAtCacheUse,
            "cursorBefore": before.cursor ?? 0, "cursorAfter": after.cursor ?? 0,
            "targetBefore": before.target ?? 0, "targetAfter": after.target ?? 0,
            "readsBefore": before.reads, "readsAfter": after.reads,
            "prefetchRangesAfterResume": b.speculation.map { [$0.lowerBound, $0.upperBound] },
            "retainedBytesBefore": retained, "retainedBytesAfterCancellation": retainedAfter,
            "maxOutstanding": b.maxOutstanding])
        try await s.awaitPlaybackCleanup()
    }

    @Test func inFlightPrefetchDrainsAndQueuedOverlapJoinsWithoutParallelRead() async throws {
        let b = Source(), s = try await make(b)
        try await prime(s, b)
        b.blockedPrefetch = 1; s.setPrefetchEnabled(true)
        try await until { b.prefetchGate != nil }
        let needed: Range<UInt64> = 192..<224, covered = coverage(s, 192..<224), before = b.demands.count
        let demand = Task { try await s.read(file, range: needed) }
        try await until { s.rangeDiagnosticSnapshot().queued.count == 1 }
        #expect(b.demands.count == before && b.outstanding == 1 && b.maxOutstanding == 1)
        #expect(s.metrics.speculativeWaitCount == 1 && covered == 0)
        s.setPrefetchEnabled(false, reason: .pause); b.releasePrefetch()
        #expect(try await demand.value == Source.bytes(needed)); try await settled(s)
        #expect(b.demands.count == before && s.metrics.joinedBytes == 32 && b.maxOutstanding == 1)
        #expect(s.metrics.speculativeWaitSeconds > 0)
        try record("demand-after-prefetch-admission", ["arrivalCoveredBytes": covered, "arrivalCoverage": "zero",
            "inFlightOverlapBytes": 32, "sourceDemandCallsForTarget": b.demands.count - before,
            "prefetchReads": b.speculation.count, "joinedBytes": s.metrics.joinedBytes,
            "speculativeWaitCount": s.metrics.speculativeWaitCount,
            "measuredGateWaitMS": s.metrics.speculativeWaitSeconds * 1000,
            "maxOutstanding": b.maxOutstanding, "bytesCorrect": true])
        try await s.awaitPlaybackCleanup()
    }
}
